import pulp

# Data
shipments_data = {
    1: [(5, 8), (4, 7), (1, 4), (2, 8), (3, 8)],  # S1
    2: [(5, 5), (3, 3), (2, 8), (1, 1), (4, 10)], # S2
    3: [(2, 1), (1, 9), (5, 2), (3, 2), (4, 7)],  # S3
    4: [(1, 5), (3, 5), (5, 4), (4, 3), (2, 10)], # S4
    5: [(3, 6), (2, 7), (1, 3), (4, 6), (5, 7)]   # S5
}

# Map: shipment -> list of (machine, duration)
jobs = list(shipments_data.keys())
machines = [1, 2, 3, 4, 5]  # H1..H5

# Operation index for each job on each machine
op_on_machine = {}
for i in jobs:
    op_on_machine[i] = {}
    for idx, (m, p) in enumerate(shipments_data[i], start=1):
        op_on_machine[i][m] = idx  # operation j of job i on machine m

# Processing times
proc_time = {}
for i in jobs:
    for idx, (m, p) in enumerate(shipments_data[i], start=1):
        proc_time[(i, idx)] = p

# Model
model = pulp.LpProblem("JobShop", pulp.LpMinimize)

# Variables
x = pulp.LpVariable.dicts("start", 
                           [(i, j) for i in jobs for j in range(1, 6)], 
                           lowBound=0, cat='Continuous')
Cmax = pulp.LpVariable("Cmax", lowBound=0, cat='Continuous')

# Binary variables for sequencing on each machine
z = {}
for m in machines:
    for i in jobs:
        if m in op_on_machine[i]:
            for k in jobs:
                if i < k and m in op_on_machine[k]:
                    z[(i, k, m)] = pulp.LpVariable(f"z_{i}_{k}_{m}", cat='Binary')

# Objective
model += Cmax

# Precedence constraints within each job
for i in jobs:
    for j in range(1, 5):
        model += x[(i, j)] + proc_time[(i, j)] <= x[(i, j+1)]

# Machine constraints
M = 150
for m in machines:
    jobs_on_m = [i for i in jobs if m in op_on_machine[i]]
    for i in jobs_on_m:
        for k in jobs_on_m:
            if i < k:
                j_i = op_on_machine[i][m]
                j_k = op_on_machine[k][m]
                model += x[(i, j_i)] + proc_time[(i, j_i)] <= x[(k, j_k)] + M * (1 - z[(i, k, m)])
                model += x[(k, j_k)] + proc_time[(k, j_k)] <= x[(i, j_i)] + M * z[(i, k, m)]

# Makespan definition
for i in jobs:
    model += x[(i, 5)] + proc_time[(i, 5)] <= Cmax

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Makespan (Cmax):", pulp.value(Cmax))
print("\nStart times for each operation:")
for i in jobs:
    print(f"Shipment {i}:", end=" ")
    for j in range(1, 6):
        print(f"Op{j}: {pulp.value(x[(i, j)]):.1f}", end=" ")
    print()

import pulp

# Data
devices = [1, 2, 3, 4]
tests = [1, 2, 3, 4]
stations = [1, 2, 3, 4]

# Operation: (device, test) -> (station, duration)
station_map = {
    (1, 1): 4, (1, 2): 1, (1, 3): 2, (1, 4): 3,
    (2, 1): 4, (2, 2): 3, (2, 3): 1, (2, 4): 2,
    (3, 1): 1, (3, 2): 3, (3, 3): 4, (3, 4): 2,
    (4, 1): 3, (4, 2): 4, (4, 3): 2, (4, 4): 1,
}
duration_map = {
    (1, 1): 9, (1, 2): 8, (1, 3): 6, (1, 4): 8,
    (2, 1): 1, (2, 2): 6, (2, 3): 6, (2, 4): 6,
    (3, 1): 10, (3, 2): 3, (3, 3): 7, (3, 4): 10,
    (4, 1): 2, (4, 2): 9, (4, 3): 1, (4, 4): 2,
}

# Model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Variables
start_vars = {}
for d in devices:
    for t in tests:
        start_vars[(d, t)] = pulp.LpVariable(f"start_d{d}_t{t}", lowBound=0, cat='Continuous')

C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Big M (sum of all durations)
M = sum(duration_map.values())

# Binary variables for ordering on same station
# Only for pairs (d1,t1) and (d2,t2) with d1 < d2 and same station
y_vars = {}
for d1 in devices:
    for t1 in tests:
        for d2 in devices:
            for t2 in tests:
                if d1 >= d2:
                    continue
                if station_map[(d1, t1)] == station_map[(d2, t2)]:
                    y_vars[(d1, t1, d2, t2)] = pulp.LpVariable(
                        f"y_d{d1}_t{t1}_d{d2}_t{t2}", cat='Binary'
                    )

# Objective
model += C_max

# Precedence within each device
for d in devices:
    for t in range(1, 4):  # t = 1,2,3
        model += (
            start_vars[(d, t)] + duration_map[(d, t)] <= start_vars[(d, t+1)],
            f"Precedence_d{d}_t{t}_to_t{t+1}"
        )

# Disjunctive constraints for same station
for d1 in devices:
    for t1 in tests:
        for d2 in devices:
            for t2 in tests:
                if d1 >= d2:
                    continue
                if station_map[(d1, t1)] == station_map[(d2, t2)]:
                    y = y_vars[(d1, t1, d2, t2)]
                    # If y=1: (d1,t1) before (d2,t2)
                    model += (
                        start_vars[(d1, t1)] + duration_map[(d1, t1)]
                        <= start_vars[(d2, t2)] + M * (1 - y),
                        f"Disj1_d{d1}_t{t1}_d{d2}_t{t2}"
                    )
                    # If y=0: (d2,t2) before (d1,t1)
                    model += (
                        start_vars[(d2, t2)] + duration_map[(d2, t2)]
                        <= start_vars[(d1, t1)] + M * y,
                        f"Disj2_d{d1}_t{t1}_d{d2}_t{t2}"
                    )

# Makespan definition
for d in devices:
    model += (
        start_vars[(d, 4)] + duration_map[(d, 4)] <= C_max,
        f"Makespan_d{d}"
    )

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Makespan:", pulp.value(C_max))
print("\nSchedule:")
for d in devices:
    for t in tests:
        s = pulp.value(start_vars[(d, t)])
        print(f"D{d}, Test{t} (Station {station_map[(d, t)]}, Dur {duration_map[(d, t)]}): Start {s:.1f}, Finish {s + duration_map[(d, t)]:.1f}")
    print()

import pulp

# Data
shipments = [1, 2, 3]
hubs = ['H1', 'H2', 'H3']

# Processing times: p[shipment][hub]
p = {
    1: {'H2': 2, 'H1': 2, 'H3': 6},
    2: {'H2': 7, 'H1': 6, 'H3': 10},
    3: {'H3': 8, 'H1': 9, 'H2': 5}
}

# Route order for each shipment
route = {
    1: [('H2', 2), ('H1', 2), ('H3', 6)],
    2: [('H2', 7), ('H1', 6), ('H3', 10)],
    3: [('H3', 8), ('H1', 9), ('H2', 5)]
}

# Model
model = pulp.LpProblem("JobShopScheduling", pulp.LpMinimize)

# Decision variables
x = {}  # start times
for i in shipments:
    for h in hubs:
        if h in p[i]:
            x[(i, h)] = pulp.LpVariable(f"x_{i}_{h}", lowBound=0, cat='Continuous')
        else:
            # Shipment doesn't visit this hub, but we don't need a variable for it
            pass

# Precedence binary variables: y[(i,j,h)] = 1 if i precedes j on hub h
y = {}
for h in hubs:
    for i in shipments:
        for j in shipments:
            if i < j and h in p[i] and h in p[j]:
                y[(i, j, h)] = pulp.LpVariable(f"y_{i}_{j}_{h}", cat='Binary')

# Makespan variable
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective
model += C_max

# Constraints

# 1. Precedence within each shipment
for i in shipments:
    ops = route[i]
    for k in range(len(ops) - 1):
        hub_curr, time_curr = ops[k]
        hub_next, time_next = ops[k + 1]
        model += x[(i, hub_curr)] + time_curr <= x[(i, hub_next)]

# 2. No overlap on each hub (disjunctive)
M = 100
for h in hubs:
    for i in shipments:
        for j in shipments:
            if i < j and h in p[i] and h in p[j]:
                model += x[(i, h)] + p[i][h] <= x[(j, h)] + M * (1 - y[(i, j, h)])
                model += x[(j, h)] + p[j][h] <= x[(i, h)] + M * y[(i, j, h)]

# 3. Makespan definition
# Completion time of each shipment = start of last operation + processing time
last_ops = {
    1: ('H3', 6),
    2: ('H3', 10),
    3: ('H2', 5)
}
for i in shipments:
    hub_last, time_last = last_ops[i]
    model += x[(i, hub_last)] + time_last <= C_max

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal makespan:", pulp.value(C_max))
print("\nStart times:")
for i in shipments:
    for h in hubs:
        if h in p[i]:
            print(f"  Shipment {i} at {h}: {pulp.value(x[(i, h)])}")

import pulp

# Define offices
offices = ["Alpha", "Beta", "Gamma", "Delta", "Epsilon"]
n = len(offices)

# Travel times in minutes (symmetric)
times = {
    ("Alpha", "Beta"): 63.4,
    ("Alpha", "Gamma"): 40.6,
    ("Alpha", "Delta"): 90.4,
    ("Alpha", "Epsilon"): 66.0,
    ("Beta", "Gamma"): 103.3,
    ("Beta", "Delta"): 153.8,
    ("Beta", "Epsilon"): 116.7,
    ("Gamma", "Delta"): 52.9,
    ("Gamma", "Epsilon"): 41.6,
    ("Delta", "Epsilon"): 74.3,
}

# Make symmetric: if (i,j) not in times, check (j,i)
def get_time(i, j):
    if i == j:
        return 0
    if (i, j) in times:
        return times[(i, j)]
    if (j, i) in times:
        return times[(j, i)]
    return float('inf')

# Create model
model = pulp.LpProblem("TSP", pulp.LpMinimize)

# Binary variables x[i][j]
x = {}
for i in range(n):
    for j in range(n):
        if i != j:
            x[i, j] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Continuous variables u[i] for MTZ
u = {}
for i in range(n):
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=0, upBound=n-1, cat='Continuous')

# Objective
obj_expr = 0
for i in range(n):
    for j in range(n):
        if i != j:
            obj_expr += get_time(offices[i], offices[j]) * x[i, j]
model += obj_expr

# Constraints: leave each city once
for i in range(n):
    model += pulp.lpSum(x[i, j] for j in range(n) if i != j) == 1

# Constraints: enter each city once
for j in range(n):
    model += pulp.lpSum(x[i, j] for i in range(n) if i != j) == 1

# MTZ subtour elimination
for i in range(1, n):
    for j in range(1, n):
        if i != j:
            model += u[i] - u[j] + n * x[i, j] <= n - 1

# Fix u for start node (Alpha = 0)
model += u[0] == 0

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output
print("Status:", pulp.LpStatus[model.status])
print("Optimal total travel time (minutes):", pulp.value(model.objective))
print("\nRoute:")
# Find route starting from Alpha
current = 0
visited = set()
while len(visited) < n:
    visited.add(current)
    for j in range(n):
        if j != current and pulp.value(x[current, j]) == 1:
            print(f"{offices[current]} -> {offices[j]}")
            current = j
            break
